package com.example.code.ui.common

import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import com.example.code.controller.LotteryController
import com.example.code.model.Lottery

// === US 02.04.02: BEGIN included campsite display ===
@Composable
fun LotteryCampsiteList(lottery: Lottery) {
    val campsites = LotteryController.includedCampsites(lottery)
    if (campsites.size > 1) {
        Text("Included campsites (${campsites.size})", style = MaterialTheme.typography.titleSmall)
        campsites.forEach { Text("• ${it.name}") }
    }
}
